--region public
---@param rewardVo MidFestivalBossDamageRewardVo
function CommonActivityBossDamageBonusCell:Refresh(rewardVo, historyMaxHurt,isDraw)
	self._damageRewardVo = rewardVo
	self._historyMaxHurt = historyMaxHurt
	self._isCanDraw = checkNumber(self._historyMaxHurt) >= checkNumber(self._damageRewardVo.upperLimit)
	self._isDraw = isDraw
	self._rewards = {}
	local rewardCount = #self._damageRewardVo.reward
	for i = 1, rewardCount do
		local reward = {
			goodsId = self._damageRewardVo.reward[i],
			num = self._damageRewardVo.rewardNum[i]
		}
		table.insert(self._rewards, reward)
	end
	self:RefreshUI()
end
--endregion public

--region private
function CommonActivityBossDamageBonusCell:RefreshUI()
	CfUtils.FillText(self.TxtDamage, self._damageRewardVo.upperLimit)
	
	---@type CommonGoodsList
	local rewardScr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
	rewardScr:FreshBaseUI(self._rewards)
	
	CfUtils.SetActive(self.Finish, self._isDraw)
	CfUtils.SetActive(self.FontStyleButton, self._isCanDraw and not self._isDraw)
	
	if self._isDraw then
		CfUtils.SetActive(self.TxtNo.gameObject,false)
	else
		CfUtils.SetActive(self.TxtNo, not self._isCanDraw)
	end
	
	CfUtils.PlayAnimator(self.AnimRoot, "Go")
end
--endregion private

